//! The expected-failures file (the ratchet): one `path: reason` line per test that is
//! known to fail, sorted by path. `#` lines are comments.

use std::collections::BTreeMap;
use std::fs;
use std::path::Path;

pub type Expected = BTreeMap<String, String>;

const HEADER: &str = "\
# test262 tests known to fail, one `path: reason` line each (paths relative to test/).
# Generated by `djs-test262 run ... --expected <this file> --update`; do not edit by hand.
";

pub fn parse(text: &str) -> Result<Expected, String> {
    let mut map = Expected::new();
    for (n, line) in text.lines().enumerate() {
        let line = line.trim_end();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (path, reason) = line
            .split_once(':')
            .ok_or_else(|| format!("line {}: expected `path: reason`", n + 1))?;
        map.insert(path.trim().to_string(), reason.trim().to_string());
    }
    Ok(map)
}

/// Loads the file; a missing file is an empty list.
pub fn load(path: &Path) -> Result<Expected, String> {
    match fs::read_to_string(path) {
        Ok(text) => parse(&text).map_err(|e| format!("{}: {e}", path.display())),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(Expected::new()),
        Err(e) => Err(format!("{}: {e}", path.display())),
    }
}

pub fn render(map: &Expected) -> String {
    let mut out = String::from(HEADER);
    for (path, reason) in map {
        out.push_str(path);
        out.push_str(": ");
        out.push_str(reason);
        out.push('\n');
    }
    out
}

pub fn save(path: &Path, map: &Expected) -> Result<(), String> {
    if let Some(dir) = path.parent() {
        fs::create_dir_all(dir).map_err(|e| format!("{}: {e}", dir.display()))?;
    }
    fs::write(path, render(map)).map_err(|e| format!("{}: {e}", path.display()))
}

#[derive(Debug, Default, PartialEq, Eq)]
pub struct Comparison {
    /// Tests that failed but are not listed: regressions.
    pub new_failures: Vec<(String, String)>,
    /// Tests that are listed but passed.
    pub stale: Vec<String>,
}

/// Compares a run against the expected failures. `results` holds every test that ran,
/// with `Some(reason)` for failures. Listed tests that did not run are ignored.
pub fn compare(expected: &Expected, results: &[(&str, Option<&str>)]) -> Comparison {
    let mut c = Comparison::default();
    for (path, failure) in results {
        match (failure, expected.contains_key(*path)) {
            (Some(reason), false) => c.new_failures.push((path.to_string(), reason.to_string())),
            (None, true) => c.stale.push(path.to_string()),
            _ => {}
        }
    }
    c
}

/// The updated list: entries for tests that ran are replaced by this run's failures;
/// entries for tests outside the run are kept.
pub fn update(expected: &Expected, results: &[(&str, Option<&str>)]) -> Expected {
    let mut map = expected.clone();
    for (path, failure) in results {
        match failure {
            Some(reason) => map.insert(path.to_string(), reason.to_string()),
            None => map.remove(*path),
        };
    }
    map
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn round_trip() {
        let text = "# c\n\nb/x.js: Test262Error: a: b\na/y.js: timeout\n";
        let map = parse(text).unwrap();
        assert_eq!(map["b/x.js"], "Test262Error: a: b");
        let rendered = render(&map);
        assert!(rendered.ends_with("a/y.js: timeout\nb/x.js: Test262Error: a: b\n"));
        assert_eq!(parse(&rendered).unwrap(), map);
        assert!(parse("no colon here").is_err());
    }

    #[test]
    fn compare_and_update() {
        let expected = parse("a.js: x\nb.js: y\nout-of-run.js: z\n").unwrap();
        let results = [("a.js", Some("x2")), ("b.js", None), ("c.js", Some("new"))];
        let c = compare(&expected, &results);
        assert_eq!(c.new_failures, [("c.js".to_string(), "new".to_string())]);
        assert_eq!(c.stale, ["b.js"]);
        let u = update(&expected, &results);
        assert_eq!(
            u.keys().collect::<Vec<_>>(),
            ["a.js", "c.js", "out-of-run.js"]
        );
        assert_eq!(u["a.js"], "x2");
    }
}
